import org.jsoup.nodes.*;
import org.jsoup.parser.*;
import org.junit.Test;
import java.io.StringReader;

public class XmlTreeBuilderTest {
  @Test
  public void defaultSettingsTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    ParseSettings result = xmlTreeBuilder.defaultSettings();
    assertNotNull(result);
    assertEquals(result, ParseSettings.preserveCase);
  }

  @Test
  public void initialiseParseTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    xmlTreeBuilder.initialiseParse(new StringReader("<html><body></body></html>"), "baseUri", new Parser(xmlTreeBuilder));
    assertTrue(xmlTreeBuilder.isTrackErrors());
  }

  @Test
  public void parseReaderTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    Document doc = xmlTreeBuilder.parse(new StringReader("<html><body></body></html>"), "baseUri");
    assertNotNull(doc);
    assertEquals("html", doc.tagName());
  }

  @Test
  public void parseStringTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    Document doc = xmlTreeBuilder.parse("<html><body></body></html>", "baseUri");
    assertNotNull(doc);
    assertEquals("html", doc.tagName());
  }

  @Test
  public void newInstanceTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    XmlTreeBuilder newInstance = xmlTreeBuilder.newInstance();
    assertNotNull(newInstance);
    assertNotEquals(xmlTreeBuilder, newInstance);
  }

  @Test
  public void processTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    boolean process = xmlTreeBuilder.process(new Token.Comment());
    assertTrue(process);
  }

  @Test
  public void insertNodeTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    xmlTreeBuilder.insert(new Token.StartTag());
    assertEquals(1, xmlTreeBuilder.stack.size());
  }

  @Test
  public void insertCommentTokenTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    xmlTreeBuilder.insert(new Token.Comment());
    assertEquals(1, xmlTreeBuilder.stack.size());
  }

  @Test
  public void insertCharacterTokenTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    xmlTreeBuilder.insert(new Token.Character("\n\r\t"));
    assertEquals(1, xmlTreeBuilder.stack.size());
  }

  @Test
  public void insertDoctypeTokenTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    xmlTreeBuilder.insert(new Token.Doctype());
    assertEquals(1, xmlTreeBuilder.stack.size());
  }

  @Test
  public void popStackToCloseTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    xmlTreeBuilder.insert(new Token.StartTag());
    xmlTreeBuilder.popStackToClose(new Token.EndTag());
    assertTrue(xmlTreeBuilder.stack.isEmpty());
  }

  @Test
  public void parseFragmentTest() {
    XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
    List<Node> nodes = xmlTreeBuilder.parseFragment("<html><body></body></html>", "baseUri", new Parser(xmlTreeBuilder));
    assertFalse(nodes.isEmpty());
    assertEquals("html", nodes.get(0).nodeName());
  }
}
